<?php

/**
 * This class has been auto-generated by the Doctrine ORM Framework
 */
class DatApariencia extends BaseDatApariencia
{
    public function setUp()
    {
    }

    /**
     * @name    devolverAparienciaUsuario
     * @author    Liv�n A Capote Vald�s
     * @access    public
     *
     * @param
     *
     * @return
     * @uses      Para buscar la configuración de un usuario
     */
    static function devolverAparienciaUsuario($idusuario)
    {
        $q = Doctrine_Query::create();
        $res = $q->select("a.*")
            ->from('DatApariencia a')
            ->where('a.idusuario = ?', $idusuario)
            ->execute();

        return $res[0] ? $res[0] : new DatApariencia();
    }

    /**
     * @name    guardarFondo
     * @author  Israel Valdés Marrero
     * @access  public
     *
     * @param
     *
     * @return
     * @uses    Para guardar el fondo de un usuario
     */
    static function guardarFondo($datos)
    {
        $dir = $datos['dirFondo'];
        $q = Doctrine_Query::create();

        return $q->update('DatApariencia a')
            ->set('a.fondo', "'$dir'")
            ->where('a.idusuario = ?', $datos['idUsuario'])
            ->execute();
    }

    /**
     * @name    guardarIconoFuncMenu
     * @author  Carlos Sarmiento
     * @access  public
     *
     * @param
     *
     * @return
     * @uses    Para guardar el icono del menu
     */
    static function guardarIconoFuncMenu($idfuncion, $name)
    {
        $q = Doctrine_Query::create();

        return $q->update('DatFuncionalidad a')
            ->set('a.icono', "'$name'")
            ->where('a.idfuncionalidad = ?', $idfuncion)
            ->execute();
    }

    /**
     * @name    imagenEnUso
     *
     * @param
     *
     * @return
     * @uses      Saber si una imagen esta en uso
     */
    static function imagenEnUso($dirImg)
    {
        $q = Doctrine_Query::create();
        $name = end(explode("/",$dirImg));
        $res = $q->select("*")
                 ->from('DatApariencia a')
                 ->where("a.fondo = ? OR a.accesosdirectos LIKE '%$name%' OR a.iniciosrapidos LIKE '%$name%'",array($dirImg))
                 ->execute();

        return count($res) ? true : false;
    }
}
